{
  "claims": [
    {
      "claim": "Direct rifampicin brain-exposure data show measurable CNS uptake: [11C]rifampicin in healthy baboons reached ~0.9-1.2 µg/mL in whole brain and estimated brain concentrations were 3-4 times above its MIC; rifampicin was also measurable in resected human brain tissue (0.29 µg/mL), monkey brain (0.87 µg/g), and mouse brain (10.25 µg/mL).",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-2",
        "Record 12-3",
        "Record 12-4",
        "Record 12-5",
        "Record 12-6"
      ]
    },
    {
      "claim": "Rifabutin, a related rifamycin, achieved meaningful CNS exposure in a rabbit TBM model (median brain concentration 536 ng/mL, brain/plasma ratio 0.856, CSF/plasma ratio 0.227) and human CSF levels averaging 50.4% of serum, supporting that rifamycin ansamycins can access the CNS in meningeal infection.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 13"
      ],
      "record_ids": [
        "Record 13-1",
        "Record 13-2",
        "Record 13-7",
        "Record 13-8"
      ]
    },
    {
      "claim": "Contradictory close-analog evidence: rifapentine, which differs mainly by a cyclopentyl rather than methyl piperazine group, had undetectable CSF in TBM patients and brain/plasma <20% in rats, showing that some rifamycin analogs do not achieve adequate CNS access.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 11"
      ],
      "record_ids": [
        "Record 11-1",
        "Record 11-2",
        "Record 11-4"
      ]
    },
    {
      "claim": "Rifamycin SV and rifamycin B were reported to cross the BBB poorly, indicating class variability, but these compounds lack the piperazine hydrazone substituent of the query.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 14",
        "Molecule 16"
      ],
      "record_ids": [
        "Record 14-1",
        "Record 14-2",
        "Record 16-1"
      ]
    }
  ],
  "final_prediction": "pass"
}

